//! Port of `src/variables/variable.h` / `src/variables/variable.cc`.
//!
//! [`Variable`] is a SecRule target (`ARGS`, `TX:foo`, `&ARGS`,
//! `!ARGS:id`, ...). In C++ every target is its own class (three per multi
//! valued variable, generated by the `DEFINE_VARIABLE*` macros); here a
//! target is one struct: its name, its key exclusions and a [`Source`]
//! saying where the values come from.

use crate::anchored_set_variable::AnchoredSetVariable;
use crate::anchored_set_variable_translation_proxy::AnchoredSetVariableTranslationProxy;
use crate::anchored_variable::AnchoredVariable;
use crate::rule_with_actions::RuleWithActions;
use crate::run_time_string::RunTimeString;
use crate::transaction::{Transaction, TransactionAnchoredVariables};
use crate::utils::regex::Regex;
use crate::utils::string::toupper_str;
use crate::variable_value::VariableValue;
use crate::variables::computed::Computed;
use crate::variables::persistent::Persistent;
use crate::variables::{VariableSelector, env, rule, xml};

// ---------------------------------------------------------------------------
// Key exclusions (`!ARGS:foo`, `!ARGS:/regex/`)
// ---------------------------------------------------------------------------

/// `KeyExclusion` and its two implementations.
#[derive(Debug)]
pub enum KeyExclusion {
    /// `KeyExclusionRegex`
    Regex(Regex),
    /// `KeyExclusionString`: stored upper case, compared case insensitively.
    String(Vec<u8>),
}

impl KeyExclusion {
    pub fn regex(re: &str) -> Self {
        KeyExclusion::Regex(Regex::new_case(re, true))
    }

    pub fn string(a: &str) -> Self {
        KeyExclusion::String(a.as_bytes().to_ascii_uppercase())
    }

    pub fn matches(&self, a: &[u8]) -> bool {
        match self {
            KeyExclusion::Regex(r) => r.search(a) > 0,
            KeyExclusion::String(k) => a.len() == k.len() && a.iter().zip(k).all(|(x, y)| x.to_ascii_uppercase() == *y),
        }
    }
}

/// `KeyExclusions`
#[derive(Debug, Default)]
pub struct KeyExclusions(pub Vec<KeyExclusion>);

impl KeyExclusions {
    pub fn new() -> Self {
        KeyExclusions(Vec::new())
    }

    /// `toOmit`
    pub fn to_omit(&self, a: &[u8]) -> bool {
        self.0.iter().any(|z| z.matches(a))
    }

    pub fn push(&mut self, k: KeyExclusion) {
        self.0.push(k);
    }

    pub fn is_empty(&self) -> bool {
        self.0.is_empty()
    }
}

// ---------------------------------------------------------------------------
// Variable
// ---------------------------------------------------------------------------

type Vars = TransactionAnchoredVariables;

/// Which entries of a multi valued variable are selected: `ARGS`,
/// `ARGS:key` or `ARGS:/regex/`.
#[derive(Debug)]
pub(crate) enum Selector {
    All,
    Key(String),
    Regex(Regex),
}

/// Which entries of a collection (`TX`, `IP`, ...) are selected. `Key` is
/// the variable's name; `Dynamic` is a key built from macros
/// (`TX:%{...}`), which is also what `setvar` & co. write to.
#[derive(Debug)]
pub(crate) enum CollectionKey {
    All,
    Key,
    /// The compiled regex and its text as written.
    Regex(Regex, String),
    Dynamic(RunTimeString),
}

/// Where the values of a variable come from.
#[derive(Debug)]
pub(crate) enum Source {
    /// A single valued variable of the transaction (`REQUEST_METHOD`).
    Single(fn(&Vars) -> &AnchoredVariable),
    /// A multi valued variable of the transaction (`ARGS`).
    Set(fn(&Vars) -> &AnchoredSetVariable, Selector),
    /// The names of a multi valued variable (`ARGS_NAMES`): the proxy and
    /// the variable it translates.
    Names(fn(&Vars) -> (&AnchoredSetVariableTranslationProxy, &AnchoredSetVariable), Selector),
    /// The `TX` collection.
    Tx(CollectionKey),
    /// A persistent collection (`IP`, `GLOBAL`, ...).
    Persistent(Persistent, CollectionKey),
    /// Properties of the rule being evaluated (`RULE:id`).
    Rule(Selector),
    /// The environment (`ENV`, `ENV:name`).
    Env,
    /// `XML`: the whole document, as a placeholder value.
    XmlDocument,
    /// `XML:/xpath`.
    XmlPath,
    /// A value computed on evaluation (`TIME`, `DURATION`, ...).
    Computed(Computed),
    /// `!VAR`: evaluates like `VAR`; rules subtract it from their targets.
    Exclusion(Box<Variable>),
    /// `&VAR`: the number of values of `VAR`.
    Count(Box<Variable>),
}

/// The writable portion of a variable, selected once rather than checked
/// again through separate dynamic-name/store/delete hooks.
pub(crate) enum WriteTarget<'v> {
    Transaction(&'v RunTimeString),
    Persistent { collection: Persistent, name: &'v RunTimeString },
}

impl WriteTarget<'_> {
    pub(crate) fn name(&self) -> &RunTimeString {
        match self {
            Self::Transaction(name) | Self::Persistent { name, .. } => name,
        }
    }

    pub(crate) fn store(&self, t: &mut Transaction<'_>, key: &[u8], value: Vec<u8>) {
        match self {
            Self::Transaction(_) => t.collections.tx.set(key, value),
            Self::Persistent { collection, .. } => {
                t.collections.persistent(*collection).set(key, t.rules.properties.web_app_id(), &value);
            }
        }
    }

    pub(crate) fn remove(&self, t: &mut Transaction<'_>, key: &[u8]) {
        match self {
            Self::Transaction(_) => t.collections.tx.remove(key),
            Self::Persistent { collection, .. } => {
                // Compatibility: SESSION deletion uses the IP key as its
                // second compartment, unlike storage and other collections.
                let second = if *collection == Persistent::Session {
                    &t.collections.ip.key
                } else {
                    t.rules.properties.web_app_id()
                };
                t.collections.persistent(*collection).remove(key, second);
            }
        }
    }
}

/// A SecRule target: its name, the keys excluded from it and where its
/// values come from.
#[derive(Debug)]
pub struct Variable {
    /// The part after the `:` (`foo` of `ARGS:foo`); empty without one.
    name: String,
    collection_name: String,
    full_name: String,
    key_exclusion: KeyExclusions,
    source: Source,
}

impl Variable {
    /// A variable called `name`: `COLLECTION:name` (or `COLLECTION.name`)
    /// is split, anything else is a collection without a name.
    pub(crate) fn new(name: &str, source: Source) -> Self {
        let (collection_name, short, full_name) = match name.find(':').or_else(|| name.find('.')) {
            Some(a) => {
                let collection = toupper_str(&name[..a]);
                let short = &name[a + 1..];
                let full = format!("{}:{}", collection, short);
                (collection, short.to_string(), full)
            }
            None => (name.to_string(), String::new(), name.to_string()),
        };
        Variable { name: short, collection_name, full_name, key_exclusion: KeyExclusions::new(), source }
    }

    /// The multi valued variable `name` (`ARGS`), narrowed by `selector`.
    /// Returns the name the variable gets and the selector.
    pub(crate) fn selected(name: &str, selector: VariableSelector) -> Option<(String, Selector)> {
        match selector {
            VariableSelector::None => Some((name.to_string(), Selector::All)),
            VariableSelector::DictElement(e) => Some((format!("{}:{}", name, e), Selector::Key(e))),
            VariableSelector::Regexp(r) => Some((regex_name(name, &r), Selector::Regex(Regex::new_case(&r, true)))),
            VariableSelector::Dynamic(_) => None,
        }
    }

    /// `!var` (C++ `VariableModificatorExclusion`), named like `var`.
    pub fn exclusion(var: Variable) -> Self {
        Self::wrapping(var, Source::Exclusion)
    }

    /// `&var` (C++ `VariableModificatorCount`), named like `var`.
    pub fn count(var: Variable) -> Self {
        Self::wrapping(var, Source::Count)
    }

    /// A variable named like `var` (without its key exclusions).
    fn wrapping(var: Variable, source: fn(Box<Variable>) -> Source) -> Self {
        Variable {
            name: var.name.clone(),
            collection_name: var.collection_name.clone(),
            full_name: var.full_name.clone(),
            key_exclusion: KeyExclusions::new(),
            source: source(Box::new(var)),
        }
    }

    pub fn name(&self) -> &str {
        &self.name
    }

    pub fn collection_name(&self) -> &str {
        &self.collection_name
    }

    pub fn full_name(&self) -> &str {
        &self.full_name
    }

    pub fn key_exclusion(&self) -> &KeyExclusions {
        &self.key_exclusion
    }

    /// Resolves the variable for `t`, appending the values to `l`. `rule`
    /// is the rule being evaluated, when there is one.
    pub fn evaluate(&self, t: &Transaction<'_>, rule: Option<&RuleWithActions>, l: &mut Vec<VariableValue>) {
        let ke = &self.key_exclusion;
        match &self.source {
            Source::Single(get) => get(&t.vars).evaluate_into(l),
            Source::Set(get, selector) => {
                let set = get(&t.vars);
                match selector {
                    Selector::All => set.resolve_with_exclusions(l, ke, Some(t)),
                    Selector::Key(key) => set.resolve_key(key.as_bytes(), l),
                    Selector::Regex(r) => set.resolve_regular_expression_with_exclusions(r, l, ke, Some(t)),
                }
            }
            Source::Names(get, selector) => {
                let (names, fount) = get(&t.vars);
                match selector {
                    Selector::All => names.resolve_with_exclusions(fount, l, ke, Some(t)),
                    Selector::Key(key) => names.resolve_key(fount, key.as_bytes(), l),
                    Selector::Regex(r) => names.resolve_regular_expression_with_exclusions(fount, r, l, ke, Some(t)),
                }
            }
            Source::Tx(key) => {
                let tx = &t.collections.tx;
                match key {
                    // The key is the name, which is empty for `TX`.
                    CollectionKey::All | CollectionKey::Key => tx.resolve_multi_matches(self.name.as_bytes(), l, ke),
                    CollectionKey::Regex(r, _) => tx.resolve_regex(r, l, ke),
                    CollectionKey::Dynamic(string) => tx.resolve_multi_matches(&string.evaluate(Some(t)), l, ke),
                }
            }
            Source::Persistent(collection, key) => {
                let binding = t.collections.persistent(*collection);
                let app = t.rules.properties.web_app_id();
                match key {
                    CollectionKey::All | CollectionKey::Key => binding.resolve(self.name.as_bytes(), app, l, ke),
                    CollectionKey::Regex(_, pattern) => binding.resolve_regex(pattern.as_bytes(), app, l, ke),
                    CollectionKey::Dynamic(string) => binding.resolve(&string.evaluate(Some(t)), app, l, ke),
                }
            }
            Source::Rule(selector) => rule::evaluate(selector, t, rule, l),
            Source::Env => env::evaluate(self, t, l),
            // The key is the variable's (empty) name.
            Source::XmlDocument => l.push(VariableValue::new(self.name.as_bytes(), b"[XML document tree]")),
            Source::XmlPath => xml::evaluate_xpath(self, t, rule, l),
            Source::Computed(c) => c.evaluate(self, t, l),
            Source::Exclusion(var) => var.evaluate(t, rule, l),
            Source::Count(var) => {
                let mut values = Vec::new();
                var.evaluate(t, rule, &mut values);
                l.push(VariableValue::new(self.full_name.as_bytes(), values.len().to_string().as_bytes()));
            }
        }
    }

    /// The selection regex, if this is a `COLLECTION:/regex/` variable.
    pub fn regex(&self) -> Option<&Regex> {
        match &self.source {
            Source::Set(_, Selector::Regex(r))
            | Source::Names(_, Selector::Regex(r))
            | Source::Rule(Selector::Regex(r)) => Some(r),
            Source::Tx(CollectionKey::Regex(r, _)) | Source::Persistent(_, CollectionKey::Regex(r, _)) => Some(r),
            _ => None,
        }
    }

    /// The variable `!var` excludes, if this is an exclusion.
    pub fn exclusion_base(&self) -> Option<&Variable> {
        match &self.source {
            Source::Exclusion(var) => Some(var),
            _ => None,
        }
    }

    /// A writable collection target exists only for dynamic-key selectors.
    /// Ordinary rule targets (including literal TX selectors) remain read-only.
    pub(crate) fn write_target(&self) -> Option<WriteTarget<'_>> {
        match &self.source {
            Source::Tx(CollectionKey::Dynamic(name)) => Some(WriteTarget::Transaction(name)),
            Source::Persistent(collection, CollectionKey::Dynamic(name)) => {
                Some(WriteTarget::Persistent { collection: *collection, name })
            }
            _ => None,
        }
    }

    /// `belongsToCollection`
    pub fn belongs_to_collection(&self, var: &Variable) -> bool {
        let a = self.collection_name.as_bytes();
        let b = var.collection_name.as_bytes();
        a.len() == b.len() && a.iter().zip(b).all(|(x, y)| x.to_ascii_uppercase() == *y)
    }

    /// `addsKeyExclusion`: if `v` is an exclusion (`!ARGS:foo`), record its
    /// key (or regex) as excluded from this variable.
    pub fn adds_key_exclusion(&mut self, v: &Variable) {
        let Some(base) = v.exclusion_base() else {
            return;
        };
        let r = match base.regex() {
            None => KeyExclusion::string(v.name()),
            Some(re) => KeyExclusion::regex(&re.pattern),
        };
        self.key_exclusion.push(r);
    }

    /// `operator==`
    pub fn same_as(&self, b: &Variable) -> bool {
        self.collection_name == b.collection_name && self.name == b.name && self.full_name == b.full_name
    }

    /// Excludes `key` from this variable (test helper).
    #[cfg(test)]
    pub(crate) fn exclude(&mut self, key: KeyExclusion) {
        self.key_exclusion.push(key);
    }
}

/// The name of a `COLLECTION:/regex/` variable (C++ `VariableRegex`).
pub(crate) fn regex_name(collection: &str, regex: &str) -> String {
    format!("{}:regex({})", collection, regex)
}

/// `Variables`: a list of (borrowed) variables.
#[derive(Default)]
pub struct Variables<'v>(pub Vec<&'v Variable>);

impl<'v> Variables<'v> {
    pub fn new() -> Self {
        Variables(Vec::new())
    }

    /// `contains(const Variable *)`
    pub fn contains_var(&self, v: &Variable) -> bool {
        self.0.iter().any(|m| v.same_as(m))
    }

    /// `contains(const VariableValue *)`
    pub fn contains_value(&self, v: &VariableValue) -> bool {
        self.0.iter().any(|m| match m.regex() {
            Some(r) => r.search(v.key()) > 0,
            None => v.key_with_collection() == m.full_name().as_bytes(),
        })
    }

    pub fn push(&mut self, v: &'v Variable) {
        self.0.push(v);
    }
}

/// `operator+(std::string, const Variables *)`: full names joined by `|`.
pub fn variables_to_string<'a, I>(vars: I) -> String
where
    I: IntoIterator<Item = &'a Variable>,
{
    let mut joined = String::new();
    for v in vars {
        if !joined.is_empty() {
            joined.push('|');
        }
        joined.push_str(v.full_name());
    }
    joined
}

// ---------------------------------------------------------------------------
// VariableMonkeyResolution
// ---------------------------------------------------------------------------

/// Error raised by the by-name resolution helpers (`std::invalid_argument`
/// "Variable not found." in C++).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct VariableNotFound;

impl std::fmt::Display for VariableNotFound {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("Variable not found.")
    }
}

impl std::error::Error for VariableNotFound {}

/// `VariableMonkeyResolution::comp`: `a` upper-cased equals `b`.
#[inline]
pub fn comp(a: &str, b: &str) -> bool {
    a.len() == b.len() && a.bytes().zip(b.bytes()).all(|(x, y)| x.to_ascii_uppercase() == y)
}

/// `VariableMonkeyResolution::stringMatchResolveMulti`: resolves a variable
/// given by name (used by the Lua engine).
pub fn string_match_resolve_multi(
    t: &Transaction<'_>,
    variable: &str,
    l: &mut Vec<VariableValue>,
) -> Result<(), VariableNotFound> {
    let delim = variable.find('.').or_else(|| variable.find(':'));
    let (col, var) = match delim {
        None => (variable.to_string(), String::new()),
        Some(d) => (variable[..d].to_string(), variable[d + 1..].to_string()),
    };
    let v = &t.vars;
    let anchored = if comp(&col, "ARGS") {
        Some(&v.args)
    } else if comp(&col, "ARGS_GET") {
        Some(&v.args_get)
    } else if comp(&col, "ARGS_POST") {
        Some(&v.args_post)
    } else if comp(&col, "FILES_SIZES") {
        Some(&v.files_sizes)
    } else if comp(&col, "FILES_NAMES") {
        Some(&v.files_names)
    } else if comp(&col, "FILES_TMP_CONTENT") {
        Some(&v.files_tmp_content)
    } else if comp(&col, "MULTIPART_FILENAME") {
        Some(&v.multipart_file_name)
    } else if comp(&col, "MULTIPART_FILENAME_CHARSET") {
        Some(&v.multipart_file_name_charset)
    } else if comp(&col, "MULTIPART_FILENAME_LANGUAGE") {
        Some(&v.multipart_file_name_language)
    } else if comp(&col, "MULTIPART_NAME") {
        Some(&v.multipart_name)
    } else if comp(&col, "MATCHED_VARS_NAMES") {
        Some(&v.matched_vars_names)
    } else if comp(&col, "MATCHED_VARS") {
        Some(&v.matched_vars)
    } else if comp(&col, "FILES") {
        Some(&v.files)
    } else if comp(&col, "REQUEST_COOKIES") {
        Some(&v.request_cookies)
    } else if comp(&col, "REQUEST_HEADERS") {
        Some(&v.request_headers)
    } else if comp(variable, "REQUEST_HEADERS_NAMES") {
        Some(&v.request_headers_names)
    } else if comp(&col, "RESPONSE_HEADERS") {
        Some(&v.response_headers)
    } else if comp(variable, "RESPONSE_HEADERS_NAMES") {
        Some(&v.response_headers_names)
    } else if comp(&col, "GEO") {
        Some(&v.geo)
    } else if comp(&col, "REQUEST_COOKIES_NAMES") {
        Some(&v.request_cookies_names)
    } else if comp(&col, "MULTIPART_PART_HEADERS") {
        Some(&v.multipart_part_headers)
    } else if comp(&col, "FILES_TMPNAMES") {
        Some(&v.files_tmp_names)
    } else {
        None
    };
    if let Some(a) = anchored {
        if delim.is_none() {
            a.resolve(l);
        } else {
            a.resolve_key(var.as_bytes(), l);
        }
        return Ok(());
    }
    let proxy = if comp(&col, "ARGS_NAMES") {
        Some((&v.args_names, &v.args))
    } else if comp(&col, "ARGS_GET_NAMES") {
        Some((&v.args_get_names, &v.args_get))
    } else if comp(&col, "ARGS_POST_NAMES") {
        Some((&v.args_post_names, &v.args_post))
    } else {
        None
    };
    if let Some((p, fount)) = proxy {
        if delim.is_none() {
            p.resolve(fount, l);
        } else {
            p.resolve_key(fount, var.as_bytes(), l);
        }
        return Ok(());
    }
    if delim.is_some() {
        return Err(VariableNotFound);
    }
    match single_anchored(t, variable) {
        Some(a) => {
            a.evaluate_into(l);
            Ok(())
        }
        None => Err(VariableNotFound),
    }
}

/// The single valued anchored variables addressable by name, in the order
/// the C++ resolution tests them.
fn single_anchored<'t>(
    t: &'t Transaction<'_>,
    variable: &str,
) -> Option<&'t crate::anchored_variable::AnchoredVariable> {
    let v = &t.vars;
    let table: [(&str, &crate::anchored_variable::AnchoredVariable); 51] = [
        ("RESPONSE_CONTENT_TYPE", &v.response_content_type),
        ("ARGS_COMBINED_SIZE", &v.args_combined_size),
        ("AUTH_TYPE", &v.auth_type),
        ("FILES_COMBINED_SIZE", &v.files_combined_size),
        ("FULL_REQUEST", &v.full_request),
        ("FULL_REQUEST_LENGTH", &v.full_request_length),
        ("INBOUND_DATA_ERROR", &v.inbound_data_error),
        ("MATCHED_VAR", &v.matched_var),
        ("MATCHED_VAR_NAME", &v.matched_var_name),
        ("MSC_PCRE_ERROR", &v.msc_pcre_error),
        ("MSC_PCRE_LIMITS_EXCEEDED", &v.msc_pcre_limits_exceeded),
        ("MULTIPART_CRLF_LF_LINES", &v.multipart_crlf_lf_lines),
        ("MULTIPART_DATA_AFTER", &v.multipart_data_after),
        ("MULTIPART_DUPLICATE_PART_HEADER", &v.multipart_duplicate_part_header),
        ("MULTIPART_FILE_LIMIT_EXCEEDED", &v.multipart_file_limit_exceeded),
        ("MULTIPART_STRICT_ERROR", &v.multipart_strict_error),
        ("MULTIPART_HEADER_FOLDING", &v.multipart_header_folding),
        ("MULTIPART_INVALID_QUOTING", &v.multipart_invalid_quoting),
        ("MULTIPART_INVALID_HEADER_FOLDING", &v.multipart_invalid_header_folding),
        ("MULTIPART_UNMATCHED_BOUNDARY", &v.multipart_unmatched_boundary),
        ("OUTBOUND_DATA_ERROR", &v.outbound_data_error),
        ("PATH_INFO", &v.path_info),
        ("QUERY_STRING", &v.query_string),
        ("REMOTE_ADDR", &v.remote_addr),
        ("REMOTE_HOST", &v.remote_host),
        ("REMOTE_PORT", &v.remote_port),
        ("REQBODY_ERROR", &v.reqbody_error),
        ("REQBODY_ERROR_MSG", &v.reqbody_error_msg),
        ("REQBODY_PROCESSOR_ERROR_MSG", &v.reqbody_processor_error_msg),
        ("REQBODY_PROCESSOR_ERROR", &v.reqbody_processor_error),
        ("REQBODY_PROCESSOR", &v.reqbody_processor),
        ("REQUEST_BASENAME", &v.request_basename),
        ("REQUEST_BODY", &v.request_body),
        ("REQUEST_BODY_LENGTH", &v.request_body_length),
        ("REQUEST_FILENAME", &v.request_filename),
        ("REQUEST_LINE", &v.request_line),
        ("REQUEST_METHOD", &v.request_method),
        ("REQUEST_PROTOCOL", &v.request_protocol),
        ("REQUEST_URI", &v.request_uri),
        ("REQUEST_URI_RAW", &v.request_uri_raw),
        ("RESOURCE", &v.resource),
        ("RESPONSE_BODY", &v.response_body),
        ("RESPONSE_CONTENT_LENGTH", &v.response_content_length),
        ("RESPONSE_PROTOCOL", &v.response_protocol),
        ("RESPONSE_STATUS", &v.response_status),
        ("SERVER_ADDR", &v.server_addr),
        ("SERVER_NAME", &v.server_name),
        ("SERVER_PORT", &v.server_port),
        ("SESSIONID", &v.session_id),
        ("UNIQUE_ID", &v.unique_id),
        ("URLENCODED_ERROR", &v.url_encoded_error),
    ];
    if comp(variable, "USERID") {
        return Some(&v.user_id);
    }
    table.iter().find(|(n, _)| comp(variable, n)).map(|(_, a)| *a)
}

/// `VariableMonkeyResolution::stringMatchResolve`: resolves a variable given
/// by name to its first value (empty if none).
pub fn string_match_resolve(t: &Transaction<'_>, variable: &str) -> Result<Vec<u8>, VariableNotFound> {
    let collection = variable.find('.').or_else(|| variable.find(':'));
    let web_app_id = t.rules.properties.web_app_id();
    let cols = &t.collections;
    let vv: Option<Vec<u8>> = match collection {
        None => {
            if let Some(a) = single_anchored(t, variable) {
                // RESOURCE is matched as an anchored variable first, as in
                // the C++ if/else chain.
                a.resolve_first()
            } else if comp(variable, "TX") {
                cols.tx.get(b"").map(<[u8]>::to_vec)
            } else if comp(variable, "USER") {
                cols.user.get(b"", web_app_id)
            } else if comp(variable, "SESSION") {
                cols.session.get(b"", web_app_id)
            } else if comp(variable, "IP") {
                cols.ip.get(b"", web_app_id)
            } else if comp(variable, "GLOBAL") {
                cols.global.get(b"", web_app_id)
            } else {
                return Err(VariableNotFound);
            }
        }
        Some(c) => {
            let col = &variable[..c];
            let var = &variable.as_bytes()[c + 1..];
            let v = &t.vars;
            if comp(col, "ARGS") {
                v.args.resolve_first(var)
            } else if comp(variable, "ARGS_NAMES") {
                v.args_names.resolve_first(&v.args, var)
            } else if comp(col, "ARGS_GET") {
                v.args_get.resolve_first(var)
            } else if comp(variable, "ARGS_GET_NAMES") {
                v.args_get_names.resolve_first(&v.args_get, var)
            } else if comp(col, "ARGS_POST") {
                v.args_post.resolve_first(var)
            } else if comp(variable, "ARGS_POST_NAMES") {
                v.args_post_names.resolve_first(&v.args_post, var)
            } else if comp(col, "FILES_SIZES") {
                v.files_sizes.resolve_first(var)
            } else if comp(col, "FILES_NAMES") {
                v.files_names.resolve_first(var)
            } else if comp(col, "FILES_TMP_CONTENT") {
                v.files_tmp_content.resolve_first(var)
            } else if comp(col, "MULTIPART_FILENAME") {
                v.multipart_file_name.resolve_first(var)
            } else if comp(col, "MULTIPART_FILENAME_CHARSET") {
                v.multipart_file_name_charset.resolve_first(var)
            } else if comp(col, "MULTIPART_FILENAME_LANGUAGE") {
                v.multipart_file_name_language.resolve_first(var)
            } else if comp(col, "MULTIPART_NAME") {
                v.multipart_name.resolve_first(var)
            } else if comp(col, "MATCHED_VARS_NAMES") {
                v.matched_vars_names.resolve_first(var)
            } else if comp(col, "MATCHED_VARS") {
                v.matched_vars.resolve_first(var)
            } else if comp(col, "FILES") {
                v.files.resolve_first(var)
            } else if comp(col, "REQUEST_COOKIES") {
                v.request_cookies.resolve_first(var)
            } else if comp(col, "REQUEST_HEADERS") {
                v.request_headers.resolve_first(var)
            } else if comp(variable, "REQUEST_HEADERS_NAMES") {
                v.request_headers_names.resolve_first(var)
            } else if comp(col, "RESPONSE_HEADERS") {
                v.response_headers.resolve_first(var)
            } else if comp(variable, "RESPONSE_HEADERS_NAMES") {
                v.response_headers_names.resolve_first(var)
            } else if comp(col, "GEO") {
                v.geo.resolve_first(var)
            } else if comp(col, "REQUEST_COOKIES_NAMES") {
                v.request_cookies_names.resolve_first(var)
            } else if comp(col, "MULTIPART_PART_HEADERS") {
                v.multipart_part_headers.resolve_first(var)
            } else if comp(col, "FILES_TMPNAMES") {
                v.files_tmp_names.resolve_first(var)
            } else if comp(col, "TX") {
                cols.tx.get(var).map(<[u8]>::to_vec)
            } else if comp(col, "RESOURCE") {
                cols.resource.get(var, web_app_id)
            } else if comp(col, "USER") {
                cols.user.get(var, web_app_id)
            } else if comp(col, "SESSION") {
                cols.session.get(var, web_app_id)
            } else if comp(col, "IP") {
                cols.ip.get(var, web_app_id)
            } else if comp(col, "GLOBAL") {
                cols.global.get(var, web_app_id)
            } else {
                return Err(VariableNotFound);
            }
        }
    };
    Ok(vv.unwrap_or_default())
}
